"""This file contains the Sim Dialogs Collimator Page Object class for the SIM COLLIMATOR pane
in the Sim Dialogs XVI test tool"""

import logging
from . import SimDialogs
from .. interactions import SimDialogCollimatorFuncs


logger = logging.getLogger(__name__)

class SimDialogsCollimator(SimDialogs):
    '''Page Object class for the SIM COLLIMATOR pane'''

    def __init__(self, host_address: str ="192.168.30.4") -> None:
        super().__init__(host_address)

    def select_sim_collimator_main_option(self, radio_btn_option: str) -> None:
        '''
        Select one of the radio button options for the Sim Collimator pane
        for the given radio button string

        Args:
            radio_btn_option (str): Name of radio button string to set

            radio_btn_option can be one of the following strings:
            "none", "S20", "M20", "L20", "M10", "L10", "M2", "L2",
            "S10", "M15", "15x15", "CTDI-S", "CTDI-M" or "CTDI-L"
        '''
        if radio_btn_option.casefold() == "none".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_none_radio_button()
        elif radio_btn_option.casefold() == "S20".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_s20_radio_button()
        elif radio_btn_option.casefold() == "M20".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_m20_radio_button()
        elif radio_btn_option.casefold() == "L20".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_l20_radio_button()
        elif radio_btn_option.casefold() == "M10".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_m10_radio_button()
        elif radio_btn_option.casefold() == "L10".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_l10_radio_button()
        elif radio_btn_option.casefold() == "M2".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_m2_radio_button()
        elif radio_btn_option.casefold() == "L2".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_l2_radio_button()
        elif radio_btn_option.casefold() == "S10".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_s10_radio_button()
        elif radio_btn_option.casefold() == "M15".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_m15_radio_button()
        elif radio_btn_option.casefold() == "15x15".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_15x15_radio_button()
        elif radio_btn_option.casefold() == "CTDI-S".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_ctdi_s_radio_button()
        elif radio_btn_option.casefold() == "CTDI-M".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_ctdi_m_radio_button()
        elif radio_btn_option.casefold() == "CTDI-L".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_ctdi_l_radio_button()
        else:
            logger.info(f"Invalid Sim Collimator radio button option: {radio_btn_option}, unable to set")

    def select_sim_collimator_filter_option(self, filter_radio_btn_option: str):
        '''
        Select one of the radio button options for the Sim Collimator filter pane
        for the given radio button string

        Args:
            filter_radio_btn_option (str): Name of radio button string to set

            filter_radio_btn_option can be one of the following strings:
            "none", "CAL1", "F1", "F2", "F0", "CAL2"
        '''
        if filter_radio_btn_option.casefold() == "none".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_filter_none_radio_button()
        elif filter_radio_btn_option.casefold() == "CAL1".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_filter_cal1_radio_button()
        elif filter_radio_btn_option.casefold() == "F1".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_filter_f1_radio_button()
        elif filter_radio_btn_option.casefold() == "F2".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_filter_f2_radio_button()
        elif filter_radio_btn_option.casefold() == "F0".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_filter_f0_radio_button()
        elif filter_radio_btn_option.casefold() == "CAL2".casefold():
            SimDialogCollimatorFuncs.click_sim_collimator_filter_cal2_radio_button()
        else:
            logger.info(f"Invalid Sim Collimator filter radio button option: {filter_radio_btn_option}, unable to set")

    def toggle_sim_collimator_kv_source_arm_locked_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the kV Source Arm Locked Checkbox in the Sim Collimator Pane to
        either checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogCollimatorFuncs.check_sim_collimator_kv_source_arm_locked_checkbox()
        else:
            SimDialogCollimatorFuncs.uncheck_sim_collimator_kv_source_arm_locked_checkbox()

    def toggle_sim_collimator_imaging_module_ref_voltage_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Imaging Module Ref Voltage in the Sim Collimator Pane to
        either checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogCollimatorFuncs.check_sim_collimator_imaging_module_ref_voltage_checkbox()
        else:
            SimDialogCollimatorFuncs.uncheck_sim_collimator_imaging_module_ref_voltage_checkbox()
